const input = $input.first().json;
const body = input.body || input;

const category = body.category || 'general'; // sales, marketing, seo, system
const priority = body.priority || 'normal'; // low, normal, high, critical

// Map category to Teams channel webhook
const channelWebhooks = {
  sales: $env.TEAMS_WEBHOOK_SALES || $env.TEAMS_WEBHOOK_URL,
  marketing: $env.TEAMS_WEBHOOK_MARKETING || $env.TEAMS_WEBHOOK_URL,
  seo: $env.TEAMS_WEBHOOK_SEO || $env.TEAMS_WEBHOOK_URL,
  system: $env.TEAMS_WEBHOOK_SYSTEM || $env.TEAMS_WEBHOOK_URL,
  general: $env.TEAMS_WEBHOOK_URL
};

const themeColor = {
  low: '808080',
  normal: '0076D7',
  high: 'FFA500',
  critical: 'FF0000'
};

// Build Adaptive Card
const card = {
  '@type': 'MessageCard',
  '@context': 'http://schema.org/extensions',
  themeColor: themeColor[priority] || '0076D7',
  summary: body.title || 'GreeVo Notification',
  sections: [{
    activityTitle: body.title || 'Notification',
    activitySubtitle: body.subtitle || new Date().toLocaleString('id-ID'),
    activityImage: 'https://via.placeholder.com/48/0076D7/FFFFFF?text=G',
    facts: (body.facts || []).map(f => ({ name: f.label, value: f.value })),
    markdown: true,
    text: body.message || ''
  }]
};

if (body.actions?.length) {
  card.potentialAction = body.actions.map(a => ({
    '@type': 'OpenUri',
    name: a.label,
    targets: [{ os: 'default', uri: a.url }]
  }));
}

return [{
  json: {
    webhook_url: channelWebhooks[category],
    card: card,
    category: category,
    priority: priority
  }
}];
